        CreatedAt = saved.CreatedAt,
        Title = saved.Title,
        Department = saved.Department,
        Location = saved.Location,
        Description = saved.Description,
        SalaryMin = saved.SalaryMin,
        SalaryMax = saved.SalaryMax,
        ClosingDate = saved.ClosingDate
    };
}
