         });
+
+    public static TimeSpan FirstPageLifetime(DateTimeOffset now) =>
+        TimeSpan.FromSeconds(Math.Min(ListLifetime.TotalSeconds,
+            Math.Floor((now.UtcDateTime.Date.AddDays(1) - now.UtcDateTime).TotalSeconds)));
