// Real end-to-end check against the clean clone of main: post a job, find it in search, open it.
const { chromium } = require('./clean-main/apps/job-posting/node_modules/@playwright/test');

(async () => {
  const title = `Final Main Check ${Date.now()}`;
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const step = message => console.log(`ok   ${message}`);

  await page.goto('http://localhost:4310/jobs/new');
  await page.locator('button[type=submit]').click();
  await page.locator('[aria-invalid=true]').first().waitFor();
  step(`empty form blocked in the browser (${await page.locator('[aria-invalid=true]').count()} invalid fields)`);

  await page.fill('#title', title);
  await page.fill('#department', 'Engineering');
  await page.fill('#location', 'Toronto');
  await page.fill('#description', 'Posted by the final check on main.');
  await page.fill('#salaryMin', '120000');
  await page.fill('#salaryMax', '100000');
  await page.fill('#closingDate', '2027-06-30');
  await page.locator('button[type=submit]').click();
  await page.locator('#salaryMax[aria-invalid=true], #salaryMin[aria-invalid=true]').first().waitFor();
  step('minimum salary above maximum rejected in the browser');

  await page.fill('#salaryMax', '150000');
  await page.locator('button[type=submit]').click();
  await page.locator('#confirmation-heading').waitFor({ timeout: 15000 });
  if (!(await page.locator('main').innerText()).includes(title)) throw new Error('confirmation does not show the saved job');
  step('job saved; confirmation shows the saved job');

  const started = Date.now();
  const search = await browser.newPage();
  for (;;) {
    await search.goto('http://localhost:4311/jobs');
    if (await search.getByText(title).count()) break;
    if (Date.now() - started > 45000) throw new Error('job did not appear in search within 45 s');
    await search.waitForTimeout(2000);
  }
  step(`job appears in the search app after ${Math.round((Date.now() - started) / 1000)} s`);

  await search.getByText(title).first().click();
  await search.getByText('Posted by the final check on main.').waitFor({ timeout: 15000 });
  step('detail page shows the full description');

  await browser.close();
})().catch(error => { console.log(`FAIL ${error.message}`); process.exit(1); });

